void dfs(TreeNode node, int depth, List<Long> sums, List<Integer> counts) {
    if (node == null) return;
    if (depth == sums.size()) {             // first node at this depth
        sums.add(0L);
        counts.add(0);
    }
    sums.set(depth, sums.get(depth) + node.val);
    counts.set(depth, counts.get(depth) + 1);
    dfs(node.left, depth + 1, sums, counts);
    dfs(node.right, depth + 1, sums, counts);
}

void dfs(TreeNode* node, int depth, vector<long long>& sums, vector<int>& counts) {
    if (node == nullptr) return;
