from collections import deque

def average_of_levels(root):
    averages = []
    queue = deque([root])
    while queue:
        size = len(queue)                   # one whole level is in the queue
        total = 0
        for _ in range(size):
            node = queue.popleft()
            total += node.val
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        averages.append(total / size)
    return averages

public List<Double> averageOfLevels(TreeNode root) {
    List<Double> averages = new ArrayList<>();
    Queue<TreeNode> queue = new ArrayDeque<>();
    queue.offer(root);
    while (!queue.isEmpty()) {
        int size = queue.size();            // one whole level is in the queue
        long sum = 0;                       // long: a level of big values can overflow int
        for (int i = 0; i < size; i++) {
            TreeNode node = queue.poll();
            sum += node.val;
            if (node.left != null) queue.offer(node.left);
            if (node.right != null) queue.offer(node.right);
        }
        averages.add((double) sum / size);
    }
    return averages;
}

vector<double> averageOfLevels(TreeNode* root) {
    vector<double> averages;
    queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
        int size = q.size();                // one whole level is in the queue
        long long sum = 0;                  // a level of big values can overflow int
        for (int i = 0; i < size; i++) {
            TreeNode* node = q.front();
            q.pop();
            sum += node->val;
            if (node->left) q.push(node->left);
            if (node->right) q.push(node->right);
        }
        averages.push_back((double) sum / size);
    }
    return averages;
}
